mapper.select:
select calcrule.YIELD
from   FIN_CASH_INFO  cash    
left join FIN_CASH_CALC_RULE calcrule    
on     cash.CASH_ID  = calcrule.CASH_ID
where  cash.CASH_TYPE_2  = #{yieldname,jdbcType=VARCHAR}
and    cash.FINPROD_ID   = #{finproid,jdbcType=VARCHAR}
and    calcrule.EFF_DATE = (select  max(calcrule2.EFF_DATE)
                            from   FIN_CASH_CALC_RULE calcrule2    
                            left  join  FIN_CASH_INFO  cash2
                            on   cash2.CASH_ID  = calcrule2.CASH_ID
                            and  cash2.FINPROD_ID = #{finproid,jdbcType=VARCHAR}
                            and  cash2.CASH_TYPE_2 = #{yieldname,jdbcType=VARCHAR}
                            )

select  mark.STATUS  as  status,
        mark.BUSINESS_DATA as datajson
from  SYS_DATA_PROCESS_MARK  mark
where mark.PAGE_ID in ('FinProductBuild001','FinProductBuild002')
and mark.BUSINESS_DATA_PK2  = #{proid,jdbcType=VARCHAR}
and mark.UPDATE_TIME = (select max(mark2.UPDATE_TIME)
                        from  SYS_DATA_PROCESS_MARK  mark2
                        where mark2.PAGE_ID in ('FinProductBuild001','FinProductBuild002')
                        and mark2.BUSINESS_DATA_PK2  = #{proid,jdbcType=VARCHAR}
                        )

select info.PATH
from  SYS_UPLOAD_FILE_INFO info
where info.BUSINESS_ID = #{finproid,jdbcType=VARCHAR}
